    const current = this.sheetState();
    if (!current) throw new Error('No sheet is loaded.');
    const made = await firstValueFrom(
      this.http.post<{ to: string }>(`/api/sheets/${encodeURIComponent(current.id)}/clone`, { to }),
    );
    return made.to;
  }
}
